interface Row {
    id: string;
    name: string;
    amount?: number;
    industry?: string;
}

function toRows(records: unknown[], limit: number = 50): Row[] {
    return records.slice(0, limit).map((record) => record as Row);
}

class RowCache {
    static instances = 0;

    #rows = new Map<string, Row>();

    get size(): number {
        return this.#rows.size;
    }

    put(rows: Row[]): number {
        let count = 0;
        for (const row of rows) {
            if (!row.id) continue;
            switch (row.name) {
                case '':
                    break;
                default:
                    this.#rows.set(row.id, row);
                    count++;
            }
        }
        return count;
    }
}

